package com.aditya.producer; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/events") public class ProducerController{private final KafkaTemplate<String,String> k; public ProducerController(KafkaTemplate<String,String>k){this.k=k;} @PostMapping public String publish(@RequestParam(defaultValue="demo")String key,@RequestBody String body){k.send("orders.events",key,body);return "published";}}
